/** A person as They owe us reads them: the spine's contact, by the customer it is or is at. */
export type TheyOweContact = Pick<Contact, 'id' | 'kind' | 'name' | 'goesBy' | 'record' | 'customerId'>

// ---------- the day a bill is due ----------

/**
 * The day we expect a bill paid, and whether it is late: the AR page's expected-pay chip for this bill. The pace read
 * is the bill's payer's, the GC on a GC-billed bill (`paySpeedPayer`), so it agrees with the Stages board. A promise
 * on the job wins over the pace. Null when there is no clock: no pay speeds, or a bill with no billed day. The flow's
 * loader stamps a Paid round's due day from the same function.
 */
export function billDueDay(
  job: Pick<BillJobRow, 'customer_id' | 'gc_customer_id' | 'bill_to_party' | 'customer_name'>,
  inv: Pick<BillInvoiceRow, 'billed_at' | 'estimated_bill_date' | 'bill_to_party' | 'bill_to_email'>,
  paySpeeds: PaySpeedData | null,
  promise: PromisedPayDate | null,
  todayYmd: string,
): ExpectedPayModel | null {
  const payer = paySpeedPayer(job, inv)
  return billedExpectedPayModel(
    { billedAtIso: inv.billed_at, estBillYmd: inv.estimated_bill_date, customerId: payer.id, payerName: payer.name },
    paySpeeds,
    todayYmd,
    promise,
  )
}

// ---------- the rows ----------

/** One row of They owe us: a person, and the worst of their open bills. */
export interface TheyOweRow {
  contactId: string
  /** What we call them in the reminder: "Dana". */
  first: string
  name: string
  customerId: string
  jobId: string
  /** Null on a job balance: a billed job with no bill row. */
  invoiceId: string | null
  /** The job's number, as the bill shows it: "1312". '' when it has none. */
  number: string
  /** The job's name, as the reminder says it: "Oakridge sewer line". */
  job: string
  /** What is still open on the bill, after what the payment rule gives it. */
  amount: number
  /** The day it was billed; null when it has no day. */
  billedYmd: string | null
  /** Days since it was billed; null when it has no day. */
  daysBilled: number | null
  /** The day of the last reminder, a send after the first; null when none went. */
  lastReminderYmd: string | null
  /** The day we expect it paid, the morning run's day to send; null when there is no clock. */
  dueYmd: string | null
  /** Past the payer's pace or past their promise. */
  late: boolean
  /** Days past the due day; 0 while it is not late. */
  daysLate: number
  /** The bill's pay page; null for a bill with no pay page, a paper bill or a job balance. */
  payUrl: string | null
  /** Their other open bills, not on the row. */
  more: number
  /** "invoice 1312 · $4,850 · 20 days · last reminder Oct 15". */
  line: string
  /** The row's right edge: "20 d". '' when the bill has no day. */
  age: string
}

/** A bill as They owe us weighs it, before it is folded to one per person. */
type OpenBill = Omit<TheyOweRow, 'more' | 'line' | 'age'>

/** Money as a bill says it: whole dollars when there are no cents, "$4,850"; "$640.50" when there are. */
export function billMoney(n: number): string {
  const cents = Math.round(n * 100)
  if (cents % 100 === 0) return `$${(cents / 100).toLocaleString('en-US')}`
  return `$${(cents / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
}

/** The person a payer's bills go to: the contact that is the customer, else the first one at it. */
function contactFor(contacts: ReadonlyArray<TheyOweContact>, customerId: string): TheyOweContact | undefined {
  const mine = contacts.filter((c) => c.kind === 'customer' && c.customerId === customerId)
  return mine.find((c) => c.record?.table === 'customers' && c.record.id === customerId) ?? mine[0]
}

/** Each bill's reminders: every send after the first, the newest day. */
function lastReminders(sends: ReadonlyArray<BillSendRow>): Map<string, string> {
  const byBill = new Map<string, string[]>()
  for (const s of sends) {
    const list = byBill.get(s.jobs_ledger_invoice_id)
    if (list) list.push(s.sent_at)
    else byBill.set(s.jobs_ledger_invoice_id, [s.sent_at])
  }
  const out = new Map<string, string>()
  for (const [id, at] of byBill) {
    if (at.length < 2) continue
    const newest = [...at].sort((a, b) => Date.parse(a) - Date.parse(b))[at.length - 1]!
    const ymd = calendarYmdInAppTzFromIso(newest)
    if (ymd) out.set(id, ymd)
  }
  return out
}

/**
 * The order of the section, and which bill stands for a person: the soonest due first, so the latest late leads; the
 * bills with no clock after them, the longest billed first; then the bigger amount.
 */
function worseFirst(a: OpenBill, b: OpenBill): number {
  if (a.dueYmd && b.dueYmd && a.dueYmd !== b.dueYmd) return a.dueYmd.localeCompare(b.dueYmd)
  if (!a.dueYmd !== !b.dueYmd) return a.dueYmd ? -1 : 1
  return (b.daysBilled ?? -1) - (a.daysBilled ?? -1) || b.amount - a.amount || (a.invoiceId ?? a.jobId).localeCompare(b.invoiceId ?? b.jobId)
}

function daysWords(n: number): string {
  return n === 0 ? 'billed today' : n === 1 ? '1 day' : `${n} days`
}

/** The row's line: what the bill is, how much, how long, and the last reminder. */
export function theyOweLine(row: Pick<TheyOweRow, 'invoiceId' | 'number' | 'amount' | 'daysBilled' | 'lastReminderYmd' | 'more'>): string {
  const what = row.invoiceId ? (row.number ? `invoice ${row.number}` : 'a bill') : row.number ? `job ${row.number} balance` : 'a job balance'
  return [
    what,
    billMoney(row.amount),
    ...(row.daysBilled !== null ? [daysWords(row.daysBilled)] : []),
    row.lastReminderYmd ? `last reminder ${shortDate(row.lastReminderYmd)}` : 'no reminder yet',
    ...(row.more > 0 ? [row.more === 1 ? '1 more bill' : `${row.more} more bills`] : []),
  ].join(' · ')
}

/**
 * They owe us: one row per person with an open bill, the worst of their bills on it, the soonest due first. A bill is
 * open when the AR page counts it owed (billed or in Collections, money still open); a bill the office marked
 * Uncollectible, a paid one, one fully paid and waiting on Mark Paid, and Owner Billing's are not rows. A bill whose
 * payer has no contact yet stays on the AR page until the spine names them.
 */
export function theyOweUs(bills: TheyOweUsBills, contacts: ReadonlyArray<TheyOweContact>, now: Date): TheyOweRow[] {
  const todayYmd = todayYmdInAppTz(now)
  const truth = computeBillTruth({ jobs: bills.jobs, invoices: bills.invoices, payments: bills.payments })
  const jobs = new Map(bills.jobs.map((j) => [j.id, j]))
  const invoices = new Map(bills.invoices.map((i) => [i.id, i]))
  const reminded = lastReminders(bills.sends)
  const open: BillTruthOpenRow[] = [...truth.billed.rows, ...truth.collections.rows].filter((r) => !r.settled)
  const byPerson = new Map<string, OpenBill[]>()
  for (const r of open) {
    const job = jobs.get(r.jobId)
    if (!job || job.billing_only) continue
    const inv = r.invoiceId ? invoices.get(r.invoiceId) : undefined
    const payer = listPayer(job, inv ?? null)
    if (!payer.id) continue
    const contact = contactFor(contacts, payer.id)
    if (!contact) continue
    const billedYmd = billedReferenceYmd({ billedAtIso: inv?.billed_at ?? null, estBillYmd: inv ? inv.estimated_bill_date : job.last_bill_date })
    const days = billedYmd ? daysBetweenYmd(billedYmd, todayYmd) : null
    // A job balance has no bill to read a pace from, as on the Stages board.
    const due = inv ? billDueDay(job, inv, bills.paySpeeds, bills.promises?.[job.id] ?? null, todayYmd) : null
    const bill: OpenBill = {
      contactId: contact.id,
      first: firstName(contact),
      name: contact.name,
      customerId: payer.id,
      jobId: job.id,
      invoiceId: inv?.id ?? null,
      number: effectiveJobLedgerNumber(job.hcp_number, job.click_number),
      job: (job.job_name ?? '').trim(),
      amount: r.remaining,
      billedYmd,
      daysBilled: days !== null && days >= 0 ? days : null,
      lastReminderYmd: inv ? reminded.get(inv.id) ?? null : null,
      dueYmd: due?.expectedYmd ?? null,
      late: due?.state === 'late',
      daysLate: due?.daysLate ?? 0,
      payUrl: inv && (inv.stripe_invoice_id ?? '').trim() && isPayLinkId(inv.id) ? payLinkUrl(inv.id) : null,
    }
    const list = byPerson.get(contact.id)
    if (list) list.push(bill)
    else byPerson.set(contact.id, [bill])
  }
  return [...byPerson.values()]
    .map((list) => {
      const worst = [...list].sort(worseFirst)[0]!
      const more = list.length - 1
      const row = { ...worst, more }
      return { ...row, line: theyOweLine(row), age: worst.daysBilled !== null ? `${worst.daysBilled} d` : '' }
    })
    .sort(worseFirst)
}

/**
 * The badge: each person with a late bill. A bill still inside the payer's pace sits in the section and waits for its
 * day without counting, as a nudge does.
 */
export function theyOweUsCount(rows: ReadonlyArray<Pick<TheyOweRow, 'late'>>): number {
  return rows.filter((r) => r.late).length
}

// ---------- the reminder, as a quick reply ----------

export type ReminderLang = 'en' | 'es'

/** The flow step the reminder belongs to: Paid, the customer's move once the bill is out. */
export const REMINDER_STEP_ID = 'paid'

/** The reminder's words, with their blanks, by language and by whether the bill has a pay page. */
export const REMINDER_WORDS: Readonly<Record<ReminderLang, { link: string; day: string }>> = {
  en: {
    link: '{first}, your bill for {job} has {amount} still open. Pay it here: {link}',
    day: '{first}, your bill for {job} has {amount} still open. Reply with the day you will pay.',
  },
  es: {
    link: '{first}, su factura de {job} tiene {amount} pendiente. Puede pagarla aquí: {link}',
    day: '{first}, su factura de {job} tiene {amount} pendiente. Responda con el día en que pagará.',
  },
}

/** What fills the reminder's blanks for one row. */
export interface ReminderFills {
  first: string
  job: string
  amount: string
  /** '' for a bill with no pay page; its line has no {link}. */
  link: string
}

/**
 * The row's bill reminder as a quick reply in the kernel's shape: a team line for customers on the Paid step, its
 * words with their blanks, and what fills them from the row. A bill with a pay page links to it; one with none asks
 * for their day, as Owner Billing's reminder does.
 */
export function reminderLine(row: Pick<TheyOweRow, 'first' | 'job' | 'amount' | 'payUrl'>, lang: ReminderLang): { reply: QuickReply; fills: ReminderFills } {
  const how = row.payUrl ? 'link' : 'day'
  const reply: QuickReply = {
    id: `they-owe-us-${how}-${lang}`,
    text: REMINDER_WORDS[lang][how],
    for: 'customer',
    stepId: REMINDER_STEP_ID,
    scope: 'team',
    addedBy: '',
    addedAt: 0,
    removed: false,
    uses: {},
    lastUsed: null,
  }
  return { reply, fills: { first: row.first, job: row.job, amount: billMoney(row.amount), link: row.payUrl ?? '' } }
}
